func getPostsWithCategoryAndLanguage(category Category, language string) []*Post {
	posts := make([]*Post, 0)
	for _, post := range SamplePosts {
		if post.Category == category && post.Language == language {
			posts = append(posts, &post)
		}
	}
	return posts
}

func RandomPostByRegion(region *FishingRegion) *Post {
	fishCache := rand.Intn(100) >= 50
	var posts []*Post
	if fishCache {
		posts = getPostsWithCategoryAndLanguage(Fishing, region.Language)
	} else {
		posts = getPostsWithCategoryAndLanguage(General, region.Language)
	}
	if len(posts) == 0 {
		return nil
	}
	return posts[rand.Intn(len(posts))]
}
